{
  "name": "@amykit/plugin-notify-fanout",
  "version": "0.7.0",
  "description": "Posts announcements to a mounted conversation, or fans them out through configured channels when no conversation is mounted.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/notify-fanout"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Every workflow that announces needs the notifier port, and this plugin mounts it. When a conversation such as slack or telegram is mounted, announcements go into the work's thread there; otherwise they fan out to every channel other plugins contribute, such as notify-inbox and notify-hermes. A channel that fails is written to the log and to stderr."
  },
  "dependencies": {
    "@amykit/core": "^0.7.0"
  }
}

import { Announcement, Conversation, Notifier } from "@amykit/core";

export interface Channel {
  name: string;
  deliver(announcement: Announcement): Promise<void>;
}

/**
 * Posts announcements to a mounted conversation, or fans them out through
 * configured channels when no conversation is mounted.
 *
 * A channel that fails does not stop the others, because losing a
 * notification must never stop a ticket.
 *
 * It still throws when *every* channel failed, and that throw now does one
 * job rather than two. "Do not let a lost notification pass unnoticed" is
 * kept, and better, by the `notify.failed` line the sink writes. "Make the
 * operator know the machine is stuck" was never something a notifier with no
 * working channel could deliver, so the engine catches it instead.
 */
export class FanOutNotifier implements Notifier {
  constructor(
    private readonly channels: readonly Channel[],
    private readonly log: (message: string) => void = console.error,
    private readonly conversation?: Conversation,
  ) {}

  async announce(announcement: Announcement): Promise<void> {
    if (this.conversation) {
      const thread = await this.conversation.open(announcement.workId, announcement.workId);
      await this.conversation.post(thread, { text: announcement.text });
      return;
    }

    if (this.channels.length === 0) {
      throw new Error("no notification channel is configured, so nothing can reach you");
    }

    const failures: string[] = [];

    for (const channel of this.channels) {
      try {
        await channel.deliver(announcement);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        failures.push(`${channel.name}: ${message}`);
        this.log(`amy could not reach you over ${channel.name}: ${message}`);
      }
    }

    if (failures.length === this.channels.length) {
      throw new Error(`every notification channel failed: ${failures.join("; ")}`);
    }
  }
}

export { FanOutNotifier } from "./FanOutNotifier.js";
export type { Channel } from "./FanOutNotifier.js";
export { CHANNEL_COLLECTION, plugin } from "./plugin.js";

import { Announcement, Conversation, Plugin, PluginContext } from "@amykit/core";
import { Channel, FanOutNotifier } from "./FanOutNotifier.js";

/** The collection other plugins add their channels to. */
export const CHANNEL_COLLECTION = "notify-channel";

/**
 * Where a channel failure goes: the log, and stderr as well.
 *
 * The log is what a report reads afterwards; stderr is what somebody
 * watching `amy run` needs to see at the moment it happens. Neither one on
 * its own covers both readers.
 */
function sinkFor(ctx: PluginContext, announcement: Announcement) {
  return (message: string): void => {
    console.error(message);
    ctx.log?.append({
      at: ctx.now().toISOString(),
      kind: "notify.failed",
      workId: announcement.workId,
      state: announcement.state,
      detail: { error: message, text: announcement.text },
    });
  };
}

export const plugin: Plugin = {
  name: "@amykit/plugin-notify-fanout",
  register(registry, ctx) {
    // Read when an announcement is made, not when this is mounted: the
    // channels are contributed by plugins listed after this one.
    registry.port("notifier", {
      announce: (announcement: Announcement) => {
        const channels = [...ctx.contributions(CHANNEL_COLLECTION).values()] as Channel[];
        const conversation = ctx.port("conversation") as Conversation | undefined;
        return new FanOutNotifier(channels, sinkFor(ctx, announcement), conversation).announce(announcement);
      },
    });
  },
};
